@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/vacd/both-maximum-bounds> ;
            sh:resultMessage "cdi:maximumValueInclusive and cdi:maximumValueExclusive both state the upper limit, and nothing checks that the two agree. W3C tabular-metadata 5.11.2, the source of these properties, treats specifying both as an error: keep one." ;
            sh:resultPath cdi:maximumValueInclusive ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ a sh:SPARQLConstraint ;
                    sh:message "cdi:maximumValueInclusive and cdi:maximumValueExclusive both state the upper limit, and nothing checks that the two agree. W3C tabular-metadata 5.11.2, the source of these properties, treats specifying both as an error: keep one." ;
                    sh:prefixes ( [ sh:namespace "http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/" ;
                                sh:prefix "cdi" ] ) ;
                    sh:select """
			PREFIX cdi: <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/>
			SELECT DISTINCT $this (cdi:maximumValueInclusive AS ?path) (?inc AS ?value)
			WHERE {
				$this cdi:maximumValueInclusive ?inc .
				$this cdi:maximumValueExclusive ?exc .
			}""" ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape cdifd:cdifValueAndConceptDescriptionBoundsShape ;
            sh:value "60.0" ] .

